mapper.select:
SELECT top_task_order.id, top_task_order.create_time, project.id 'project.id', project.`name` 'project.name', project.short_name 'project.short_name', project.serial_number 'project.serial_number', monomer.id 'monomer.id', monomer.`name` 'monomer.name', area.`id` 'area.id', area.`name` 'area.name', top_task_order.order_number, top_task_order.quantity, top_task_order.production_line_type_enum, top_task_order.ask_complete_time, IFNULL(task.task.task_quantity,0)'totalMete.quantity', IFNULL(task.task_net_weight,0)'totalMete.net_weight', IFNULL(task.task_gross_weight,0)'totalMete.gross_weight', IFNULL(task.complete_quantity,0)'totalCompleteMete.quantity', IFNULL(task.complete_net_weight,0)'totalCompleteMete.net_weight', IFNULL(task.complete_gross_weight,0)'totalCompleteMete.gross_weight' FROM mes_building_top_task_order top_task_order LEFT JOIN contract_project project ON top_task_order.project_id=project.id LEFT JOIN plan_monomer monomer ON monomer.id=top_task_order.monomer_id LEFT JOIN plan_area area ON area.id=top_task_order.area_id LEFT JOIN (SELECT task_order.top_task_order_id, sum( task_order.task_quantity ) task_quantity, sum( task_order.task_net_weight ) task_net_weight, sum( task_order.task_gross_weight ) task_gross_weight, sum( task_order.complete_quantity ) complete_quantity, sum( task_order.complete_net_weight ) complete_net_weight, sum( task_order.complete_gross_weight ) complete_gross_weight FROM (SELECT task_order.top_task_order_id, task.task_quantity, task.task_net_weight, task.task_gross_weight, task.complete_quantity, task.complete_net_weight, task.complete_gross_weight FROM (SELECT task_order_id, sum(task_quantity) task_quantity, sum(net_weight) task_net_weight, sum(gross_weight) task_gross_weight, sum(complete_quantity) complete_quantity, sum(complete_net_weight) complete_net_weight, sum(complete_gross_weight) complete_gross_weight FROM (SELECT task_order_id, task_quantity task_quantity, task_quantity*product.net_weight net_weight, task_quantity*product.gross_weight gross_weight, complete_quantity complete_quantity, complete_quantity*product.net_weight complete_net_weight, complete_quantity*product.gross_weight complete_gross_weight FROM mes_building_task task LEFT JOIN tech_artifact product ON task.product_id =product.id WHERE task.task_type_enum=2 AND task.bool_delete_enum=0 AND task.task_quantity>complete_quantity
AND task.project_id IN
#{projectId}
AND task.monomer_id = #{monomerId}
AND task.area_id = #{areaId}
AND product.serial_number like CONCAT('%', #{serialNumber},'%')
)task GROUP BY task_order_id) task LEFT JOIN mes_building_task_order task_order ON task_order.id=task.task_order_id) task_order GROUP BY task_order.top_task_order_id) task ON top_task_order.id=task.top_task_order_id WHERE top_task_order.complete_time IS NULL AND task.task_quantity>task.complete_quantity
AND date_format(top_task_order.create_time, '%Y-%m') =date_format(#{dateTime}, '%Y-%m')
AND top_task_order.project_id IN
#{projectId}
ORDER BY top_task_order.ask_complete_time,IFNULL(task.task.task_quantity,0)-IFNULL(task.task_net_weight,0)
